# Deployment "especializado" con modelo falso: corre en su propio langgraph dev.
import time

from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.messages import AIMessage
from langchain_core.outputs import ChatGeneration, ChatResult
from langchain_core.tools import tool
from deepagents import create_deep_agent

SALES = [
    ("West", "Widget", 1200, 36000), ("West", "Gadget", 850, 42500),
    ("East", "Widget", 980, 29400), ("East", "Gadget", 1400, 70000),
    ("Central", "Widget", 630, 18900), ("Central", "Gadget", 720, 36000),
]


@tool
def analyze_sales(group_by: str = "region") -> str:
    """Run a full sales breakdown, grouped by "region" or by "product"."""
    time.sleep(8)  # simula un trabajo lento (el lab usa 20 s)
    col = 1 if group_by == "product" else 0
    tot = {}
    for row in SALES:
        u, r = tot.get(row[col], (0, 0))
        tot[row[col]] = (u + row[2], r + row[3])
    orden = sorted(tot.items(), key=lambda kv: -kv[1][1])
    return "\n".join(f"{k}: ${r:,} revenue, {u:,} units" for k, (u, r) in orden)


class Analista(BaseChatModel):
    """Modelo falso: llama analyze_sales una vez y devuelve su resultado."""

    @property
    def _llm_type(self):
        return "analista"

    def bind_tools(self, tools, **kw):
        return self

    def _generate(self, messages, stop=None, run_manager=None, **kw):
        last = messages[-1]
        if last.type == "tool":
            msg = AIMessage(content=last.content)
        else:
            g = "product" if "product" in last.content else "region"
            msg = AIMessage(content="", tool_calls=[{"name": "analyze_sales", "args": {"group_by": g}, "id": "a1"}])
        return ChatResult(generations=[ChatGeneration(message=msg)])


graph = create_deep_agent(model=Analista(), tools=[analyze_sales])

import re
import time

from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.messages import AIMessage
from langchain_core.outputs import ChatGeneration, ChatResult
from langgraph.checkpoint.memory import MemorySaver
from deepagents import AsyncSubAgent, create_deep_agent


class Supervisor(BaseChatModel):
    """Modelo falso del agente principal.

    - Si el usuario pide "analiza", lanza la tarea con start_async_task.
    - Si pide "¿ya?", revisa la tarea con check_async_task.
    - Si lo último es un ToolMessage, repite lo que dijo la tool.
    """

    task_id: str = ""

    @property
    def _llm_type(self):
        return "supervisor"

    def bind_tools(self, tools, **kw):
        print("Tools del supervisor:", [t.name for t in tools])
        return self

    def _generate(self, messages, stop=None, run_manager=None, **kw):
        last = messages[-1]
        if last.type == "tool":
            m = re.search(r"task_id: (\S+)", last.content)
            if m:
                self.task_id = m.group(1)
            msg = AIMessage(content=f"(tool) {last.content[:160]}")
        elif "analiza" in last.content:
            msg = AIMessage(content="", tool_calls=[{
                "name": "start_async_task",
                "args": {"subagent_type": "analyst", "description": "Analyze sales by region."},
                "id": "s1"}])
        else:
            msg = AIMessage(content="", tool_calls=[{
                "name": "check_async_task", "args": {"task_id": self.task_id}, "id": f"c{len(messages)}"}])
        return ChatResult(generations=[ChatGeneration(message=msg)])


subagents = [
    AsyncSubAgent(
        name="analyst",
        description="Runs sales analysis grouped by region or by product. Slow.",
        graph_id="agent",
        url="http://127.0.0.1:2078",
    ),
]

agent = create_deep_agent(model=Supervisor(), subagents=subagents, checkpointer=MemorySaver())
cfg = {"configurable": {"thread_id": "jane"}}

for pregunta, espera in [("analiza las ventas por región", 0), ("¿ya?", 0), ("¿ya?", 10)]:
    time.sleep(espera)
    t0 = time.time()
    r = agent.invoke({"messages": [{"role": "user", "content": pregunta}]}, cfg)
    print(f"\n> {pregunta}  ({time.time() - t0:.1f} s)")
    print(r["messages"][-1].content)
    print("async_tasks en el state:", {k[:8]: v["status"] for k, v in r["async_tasks"].items()})
